package com.fakelegacy.customer;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class CustomerController {

    private static final Pattern VAT_FR = Pattern.compile("FR\\d{11}");
    private static final Pattern COUNTRY = Pattern.compile("[A-Za-z]{2}");
    private static final BigDecimal DEFAULT_B2B_CREDIT = new BigDecimal("5000.00");

    @Autowired
    private CustomerDao customerDao;
    @Autowired
    private AddressDao addressDao;
    @Autowired
    private OrderServiceClient orderClient;

    // U1
    @PostMapping("/customers")
    @Transactional
    @SuppressWarnings("unchecked")
    public Map<String, Object> register(@RequestBody Map<String, Object> body) {
        String email = str(body.get("email"));
        String type = str(body.get("type"));
        if (email == null || !email.matches("[^@\\s]+@[^@\\s]+\\.[^@\\s]+")) {
            return Responses.error("invalid email");
        }
        if (!"B2C".equals(type) && !"B2B".equals(type)) {
            return Responses.error("type must be B2C or B2B");
        }
        String companyName = str(body.get("companyName"));
        String vatNumber = str(body.get("vatNumber"));
        if ("B2B".equals(type)) {
            if (companyName == null) {
                return Responses.error("companyName is required for B2B");
            }
            if (vatNumber == null || !VAT_FR.matcher(vatNumber).matches()) {
                return Responses.error("vatNumber is required for B2B and must match FR + 11 digits");
            }
        }
        if (customerDao.emailExists(email)) {
            return Responses.error("email already registered");
        }

        List<Address> addresses = new ArrayList<>();
        Object rawAddresses = body.get("addresses");
        if (rawAddresses != null) {
            try {
                addresses = parseAddresses((List<Map<String, Object>>) rawAddresses);
            } catch (IllegalArgumentException | ClassCastException e) {
                return Responses.error(e.getMessage() == null ? "invalid addresses" : e.getMessage());
            }
        }

        Customer c = new Customer();
        c.setEmail(email);
        c.setType(type);
        c.setCompanyName("B2B".equals(type) ? companyName : null);
        c.setVatNumber("B2B".equals(type) ? vatNumber : null);
        c.setRegisteredAt(LocalDateTime.now());
        c.setBlacklisted(false);
        c.setLoyaltyPoints(0);
        c.setCreditLimit("B2B".equals(type) ? DEFAULT_B2B_CREDIT : BigDecimal.ZERO.setScale(2));
        c.setCreditOutstanding(BigDecimal.ZERO.setScale(2));
        long id;
        try {
            id = customerDao.insert(c);
        } catch (DuplicateKeyException e) {
            return Responses.error("email already registered");
        }
        if (!addresses.isEmpty()) {
            addressDao.replaceAll(id, addresses);
        }
        Map<String, Object> res = Responses.ok();
        res.put("id", id);
        res.put("email", email);
        res.put("type", type);
        return res;
    }

    // U2
    @GetMapping("/customers/{id}")
    public Map<String, Object> get(@PathVariable("id") long id) {
        Customer c = customerDao.findById(id);
        if (c == null) {
            return Responses.error("customer not found");
        }
        String tier;
        if (c.getTierOverride() != null) {
            tier = c.getTierOverride();
        } else if (c.isBlacklisted()) {
            tier = "STANDARD";
        } else {
            tier = TierCache.getInstance().get(id);
            if (tier == null) {
                BigDecimal revenue = orderClient.revenue12m(id);
                if (revenue == null) {
                    tier = floorTier("STANDARD", c.getMinTier());
                } else {
                    tier = floorTier(TierCalculator.compute(revenue), c.getMinTier());
                    TierCache.getInstance().put(id, tier);
                }
            }
        }

        Map<String, Object> res = Responses.ok();
        res.put("id", c.getId());
        res.put("email", c.getEmail());
        res.put("type", c.getType());
        res.put("companyName", c.getCompanyName());
        res.put("vatNumber", c.getVatNumber());
        res.put("registeredAt", c.getRegisteredAt().toString());
        res.put("blacklisted", c.isBlacklisted());
        res.put("tier", tier);
        res.put("tierOverride", c.getTierOverride());
        res.put("loyaltyPoints", c.getLoyaltyPoints());
        res.put("creditLimit", c.getCreditLimit());
        res.put("creditOutstanding", c.getCreditOutstanding());
        List<Map<String, Object>> addrs = new ArrayList<>();
        for (Address a : addressDao.findByCustomer(id)) {
            Map<String, Object> m = new LinkedHashMap<>();
            m.put("country", a.getCountry());
            m.put("city", a.getCity());
            m.put("line", a.getLine());
            m.put("defaultShipping", a.isDefaultShipping());
            addrs.add(m);
        }
        res.put("addresses", addrs);
        return res;
    }

    // U3
    @PutMapping("/customers/{id}/addresses")
    @Transactional
    public Map<String, Object> replaceAddresses(@PathVariable("id") long id, @RequestBody List<Map<String, Object>> body) {
        if (customerDao.findById(id) == null) {
            return Responses.error("customer not found");
        }
        List<Address> addresses;
        try {
            addresses = parseAddresses(body);
            addressDao.checkMax(addresses);
        } catch (IllegalArgumentException e) {
            return Responses.error(e.getMessage());
        }
        if (addresses.isEmpty()) {
            return Responses.error("at least one address is required");
        }
        addressDao.replaceAll(id, addresses);
        Map<String, Object> res = Responses.ok();
        res.put("count", addresses.size());
        return res;
    }

    // U9
    @PostMapping("/customers/{id}/blacklist")
    public Map<String, Object> blacklist(@PathVariable("id") long id,
            @RequestParam(name = "value", defaultValue = "true") boolean value) {
        if (customerDao.findById(id) == null) {
            return Responses.error("customer not found");
        }
        customerDao.setBlacklisted(id, value);
        Map<String, Object> res = Responses.ok();
        res.put("id", id);
        res.put("blacklisted", value);
        return res;
    }

    private List<Address> parseAddresses(List<Map<String, Object>> raw) {
        List<Address> list = new ArrayList<>();
        int defaults = 0;
        for (Map<String, Object> m : raw) {
            String country = str(m.get("country"));
            String city = str(m.get("city"));
            String line = str(m.get("line"));
            if (country == null || !COUNTRY.matcher(country).matches()) {
                throw new IllegalArgumentException("address country must be a 2-letter code");
            }
            if (city == null || line == null) {
                throw new IllegalArgumentException("address city and line are required");
            }
            Address a = new Address();
            a.setCountry(country.toUpperCase());
            a.setCity(city);
            a.setLine(line);
            a.setDefaultShipping(Boolean.TRUE.equals(m.get("defaultShipping")));
            if (a.isDefaultShipping()) {
                defaults++;
            }
            list.add(a);
        }
        addressDao.checkMax(list);
        if (!list.isEmpty() && defaults != 1) {
            throw new IllegalArgumentException("exactly one address must be defaultShipping");
        }
        return list;
    }

    private static String floorTier(String tier, String minTier) {
        if (minTier != null && TierCalculator.rank(tier) < TierCalculator.rank(minTier)) {
            return minTier;
        }
        return tier;
    }

    private static String str(Object o) {
        if (o == null) {
            return null;
        }
        String s = String.valueOf(o).trim();
        return s.isEmpty() ? null : s;
    }
}
